141	  const controls = new OrbitControls(cam, renderer.domElement);
142	  controls.enableDamping = true;
143	  controls.minDistance = car.orbit?.min ?? 0.8; controls.maxDistance = car.orbit?.max ?? 16;
144	
145	  // Camera fitted to the museum photo (tools/fit-photo-camera.mjs): position in mm, yaw/pitch/roll in rad, focal length in px.
146	  let photoCam = null;
147	  if (photo) {
148	    const { c, yaw, pitch, roll, f } = photo.cam;
149	    photoCam = new THREE.PerspectiveCamera(2 * Math.atan(photo.h / 2 / f) * 180 / Math.PI, aspect, 0.05, 60);
150	    const fw = new THREE.Vector3(Math.cos(pitch) * Math.cos(yaw), Math.cos(pitch) * Math.sin(yaw), Math.sin(pitch));
151	    const r = new THREE.Vector3().crossVectors(fw, new THREE.Vector3(0, 0, 1)).normalize();
152	    const u = new THREE.Vector3().crossVectors(r, fw);
153	    photoCam.position.copy(mm(c));
154	    photoCam.up.copy(u.clone().multiplyScalar(Math.cos(roll)).addScaledVector(r, -Math.sin(roll)));
155	    photoCam.lookAt(photoCam.position.clone().add(fw));
156	  }
157	
158	  // Physically based light units since r155: intensities are the PoC's r128 values × π.
159	  scene.add(new THREE.HemisphereLight(0xffffff, 0x445566, 0.95 * Math.PI));
160	  const sun = new THREE.DirectionalLight(0xffffff, 0.65 * Math.PI); sun.position.set(...(car.sun ?? [3, 4, 6])); scene.add(sun);
161	
162	  // Theme: colours live in CSS custom properties; bind(color, token) re-applies them on theme change.
163	  const root = document.documentElement;
164	  const css = n => getComputedStyle(root).getPropertyValue(n).trim();
165	  const cache = new Map(), bindings = [], onTheme = [];
166	  const color = token => { if (!cache.has(token)) cache.set(token, new THREE.Color(css(token))); return cache.get(token); };
167	  const isDark = () => root.dataset.theme === "dark" || (root.dataset.theme !== "light" && matchMedia("(prefers-color-scheme: dark)").matches);
168	  let onPhoto = false;
169	  function applyColors() {
170	    cache.clear();
171	    for (const [c, token] of bindings) c.copy(color(token));
172	    scene.background = onPhoto ? null : color("--stage").clone();
173	    for (const fn of onTheme) fn({ onPhoto, dark: isDark() });
174	  }
175	  matchMedia("(prefers-color-scheme: dark)").addEventListener("change", applyColors);
176	  new MutationObserver(applyColors).observe(root, { attributes: true, attributeFilter: ["data-theme"] });
177	
178	  function resize() {
179	    const w = el.clientWidth, h = el.clientHeight;
180	    if (!w || !h) return;
181	    renderer.setSize(w, h, false); cam.aspect = w / h; cam.updateProjectionMatrix();
182	  }
183	  new ResizeObserver(resize).observe(el);
184	
185	  const stats = { frames: 0 };
186	  return {
187	    THREE, renderer, scene, cam, photoCam, controls, css, color, isDark, stats,
188	    bind(c, token) { bindings.push([c, token]); c.copy(color(token)); return c; },
189	    tokenMat(token, o) { const m = new THREE.MeshStandardMaterial({ roughness: 0.5, metalness: 0.15, ...o }); this.bind(m.color, token); return m; },
190	    onTheme(fn) { onTheme.push(fn); },
191	    applyColors,
192	    setPhotoView(on) { onPhoto = on && !!photoCam; controls.enabled = !onPhoto; applyColors(); },
193	    setOrbit(v) { cam.position.set(...v.pos); controls.target.set(...v.target); controls.update(); },
194	    // onFrame(dt) runs before each render; dt in s, clamped so a paused tab or slow frame never jumps the simulation.
195	    // stop() pauses the loop (the canvas keeps its last frame); start() again resumes it.
196	    stop() { renderer.setAnimationLoop(null); },
197	    start(onFrame) {
198	      resize();
199	      let last = performance.now();
200	      renderer.setAnimationLoop(now => {
201	        const dt = Math.min((now - last) / 1000, 0.05); last = now;
202	        onFrame(dt);
203	        if (!onPhoto) controls.update();
204	        renderer.render(scene, onPhoto ? photoCam : cam);
205	        stats.frames++;
206	      });
207	    },
208	  };
