210	// 2-D wind tunnel on the car's centre plane: lattice Boltzmann (D2Q9, BGK collision with a Smagorinsky eddy viscosity, so
211	// the wake can turn turbulent without the solver blowing up). Pure: no DOM, no three.js.
212	// Lattice units: one cell, one step. Air enters at column i = 0 with speed U and leaves at i = nx − 1. Row j = 0 sits on the
213	// road, which moves with the air (car frame: the road streams past at the car's speed, so it grows no boundary layer). The
214	// top is a free-slip wall; the body (solid cells) is a no-slip wall (half-way bounce-back).
215	const CX = [0, 1, 0, -1, 0, 1, -1, -1, 1], CZ = [0, 0, 1, 0, -1, 1, 1, -1, -1];
216	const W = [4 / 9, 1 / 9, 1 / 9, 1 / 9, 1 / 9, 1 / 36, 1 / 36, 1 / 36, 1 / 36];
217	const OPP = [0, 3, 4, 1, 2, 7, 8, 5, 6], MIRROR_Z = [0, 1, 4, 3, 2, 8, 7, 6, 5];
218	
219	// Side profile (closed polygon of [x, z] in mm, x forward) → solid cells. Cell (i, j) has its centre at
220	// x = x0 − (i + ½)·cell, z = ground + (j + ½)·cell: the tunnel runs from the front edge x0 back to x1, up to top.
221	export function rasterize(profile, { x0, x1, top, cell, ground = 0 }) {
222	  const nx = Math.round((x0 - x1) / cell), nz = Math.round(top / cell), solid = new Uint8Array(nx * nz);
223	  for (let j = 0; j < nz; j++) for (let i = 0; i < nx; i++) {
224	    const x = x0 - (i + 0.5) * cell, z = ground + (j + 0.5) * cell;
225	    let inside = false;
226	    for (let a = 0, b = profile.length - 1; a < profile.length; b = a++) {
227	      const [xa, za] = profile[a], [xb, zb] = profile[b];
228	      if ((za > z) !== (zb > z) && x < xa + (z - za) / (zb - za) * (xb - xa)) inside = !inside;
229	    }
230	    solid[j * nx + i] = inside ? 1 : 0;
231	  }
232	  return { nx, nz, solid };
233	}
234	
235	export function createTunnel({ nx, nz, solid, U = 0.1, nu = 0.0015, smag = 0.16 }) {
236	  const N = nx * nz, tau0 = 3 * nu + 0.5, C = 18 * Math.SQRT2 * smag * smag, uu = 1.5 * U * U;
237	  let f = new Float32Array(9 * N), g = new Float32Array(9 * N);
238	  const ux = new Float32Array(N).fill(U), uz = new Float32Array(N), rho = new Float32Array(N).fill(1);
239	  const inflow = W.map((w, k) => w * (1 + 3 * CX[k] * U + 4.5 * (CX[k] * U) ** 2 - uu));
240	  for (let c = 0; c < N; c++) { f.set(inflow, 9 * c); if (solid[c]) ux[c] = 0; }
241	  const fe = new Float64Array(9), fo = new Float64Array(9);
242	  // Drag on the body this step (lattice force units, + = downstream): total by momentum exchange at the walls; the pressure
243	  // part split into push on upstream-facing faces and suction on downstream-facing ones; friction is the rest.
244	  const drag = { total: 0, push: 0, suction: 0, friction: 0 };
245	
246	  function step() {
247	    let fx = 0, rf = 0, nf = 0, rr = 0, nr = 0;
248	    for (let j = 0; j < nz; j++) for (let i = 0; i < nx; i++) {
249	      const c = j * nx + i; if (solid[c]) continue;
250	      const o = 9 * c;
251	      let r = 0, mx = 0, mz = 0;
252	      for (let k = 0; k < 9; k++) { const v = f[o + k]; r += v; mx += CX[k] * v; mz += CZ[k] * v; }
253	      const u = mx / r, w = mz / r, q = 1.5 * (u * u + w * w);
254	      rho[c] = r; ux[c] = u; uz[c] = w;
255	      let pxx = 0, pzz = 0, pxz = 0;
256	      for (let k = 0; k < 9; k++) {
257	        const cu = 3 * (CX[k] * u + CZ[k] * w), e = W[k] * r * (1 + cu + 0.5 * cu * cu - q), d = f[o + k] - e;
258	        fe[k] = e; fo[k] = d; pxx += CX[k] * CX[k] * d; pzz += CZ[k] * CZ[k] * d; pxz += CX[k] * CZ[k] * d;
259	      }
260	      // Smagorinsky: the local strain (from the non-equilibrium stress) raises the relaxation time where the flow shears.
261	      const tau = 0.5 * (tau0 + Math.sqrt(tau0 * tau0 + C * Math.sqrt(pxx * pxx + pzz * pzz + 2 * pxz * pxz) / r)), om = 1 / tau;
262	      for (let k = 0; k < 9; k++) {
263	        const v = fe[k] + (1 - om) * fo[k], ti = i + CX[k], tj = j + CZ[k];
264	        if (tj < 0) g[o + OPP[k]] = v - 6 * W[k] * r * CX[k] * U;                       // road moving at U
265	        else if (tj >= nz) { if (ti >= 0 && ti < nx) g[9 * (j * nx + ti) + MIRROR_Z[k]] = v; }   // free-slip top
266	        else if (ti < 0 || ti >= nx) continue;                                           // inlet / outlet, set below
267	        else if (solid[tj * nx + ti]) {                                                  // bounce back off the body
268	          g[o + OPP[k]] = v; fx += 2 * v * CX[k];
269	          if (k === 1) { rf += r; nf++; } else if (k === 3) { rr += r; nr++; }
270	        }
271	        else g[9 * (tj * nx + ti) + k] = v;
272	      }
273	    }
274	    for (let j = 0; j < nz; j++) {
275	      g.set(inflow, 9 * j * nx);
276	      g.copyWithin(9 * (j * nx + nx - 1), 9 * (j * nx + nx - 2), 9 * (j * nx + nx - 1));  // zero-gradient outlet
277	    }
278	    [f, g] = [g, f];
279	    // Reference pressure p∞: the oncoming air a few cells behind the inlet (drag builds a pressure drop along the tunnel, so
280	    // the inlet's own density is not the free stream's).
281	    let s = 0, n = 0; for (let j = 0; j < nz; j++) if (!solid[j * nx + 3]) { s += rho[j * nx + 3]; n++; }
282	    ref = s / n;
283	    drag.total = fx; drag.push = (rf - nf * ref) / 3; drag.suction = -(rr - nr * ref) / 3; drag.friction = fx - drag.push - drag.suction;
284	  }
285	
286	  // Pressure coefficient (p − p∞) / ½ρU² at cell c: lattice pressure is ρ/3.
287	  let ref = 1;
288	  const cp = c => (rho[c] - ref) / 3 / (0.5 * U * U);
289	  // Bilinear velocity at fractional cell coordinates (cell centres at integers), for tracer particles. Solid cells read 0.
290	  function sample(x, z, out) {
291	    const i = Math.max(0, Math.min(nx - 1.001, x)), j = Math.max(0, Math.min(nz - 1.001, z)), i0 = i | 0, j0 = j | 0, a = i - i0, b = j - j0;
292	    const c = j0 * nx + i0, w00 = (1 - a) * (1 - b), w10 = a * (1 - b), w01 = (1 - a) * b, w11 = a * b;
293	    out[0] = w00 * ux[c] + w10 * ux[c + 1] + w01 * ux[c + nx] + w11 * ux[c + nx + 1];
294	    out[1] = w00 * uz[c] + w10 * uz[c + 1] + w01 * uz[c + nx] + w11 * uz[c + nx + 1];
295	    return out;
296	  }
297	  return { nx, nz, U, solid, ux, uz, rho, drag, step, cp, sample };
298	}
