// One component's precomputed airflow (tools/cfd/part.mjs → stops/<slug>/cfd/<part>/, shown by subsystems/race-aero.js):
// a flat grid of one scalar per cell on a plane through the part, the same for every case of the part, plus per case the
// mean-flow paths and the guides (arrows, lines) that carry its lesson. Pure: no DOM, no three.js, no file access.
//
// field.json: { plane: "xz" | "xy", originMm: [x, y, z] (centre of the first cell), cellMm, width, height, quantity,
//   range: [lo, hi], cases: { <id>: { lines: [[[x, y, z], …], …], guides: [{ kind: "arrow" | "line", points, faint? }],
//   follow?: [line index] } } }. Points in vehicle mm (x forward, y left, z up).
// <id>.bin: width · height bytes, row-major, rows from the bottom. Advancing a column always decreases x (the air's way);
// advancing a row increases z on an "xz" plane and y on an "xy" plane. 255 marks a solid cell; the field's range maps
// onto 0…254 with rounding and clamping.
export const SOLID = 255;
export const PLANES = ["xz", "xy"];
export const QUANTITIES = ["vertical-speed-over-inlet", "pressure-coefficient", "speed-over-inlet"];

// Centre of cell (a, b) in mm.
export function centre({ plane, originMm: [x, y, z], cellMm: h }, a, b) {
  return plane === "xz" ? [x - a * h, y, z + b * h] : [x - a * h, y + b * h, z];
}

// The grid's outer corners in mm, in texture order: (u, v) = (0, 0), (1, 0), (0, 1), (1, 1); u runs with the columns, v up
// the rows. Each cell is a square of side cellMm around its centre.
export function corners(f) {
  const lo = centre(f, -0.5, -0.5), u = centre(f, f.width - 0.5, -0.5), v = centre(f, -0.5, f.height - 0.5), uv = centre(f, f.width - 0.5, f.height - 0.5);
  return [lo, u, v, uv];
}

export const quantize = (v, [lo, hi]) => Math.max(0, Math.min(254, Math.round((v - lo) / (hi - lo) * 254)));
export const dequantize = (byte, [lo, hi]) => (byte === SOLID ? null : lo + byte / 254 * (hi - lo));

// The bytes of one case: sample(x, y, z) gives the field's value at a cell centre, or null for a solid cell.
export function encode(f, sample) {
  const out = new Uint8Array(f.width * f.height);
  for (let b = 0; b < f.height; b++) for (let a = 0; a < f.width; a++) {
    const v = sample(...centre(f, a, b));
    out[b * f.width + a] = v == null ? SOLID : quantize(v, f.range);
  }
  return out;
}

// One case's bytes read back: at(a, b) → value, or null for a solid cell. Throws on a wrong byte count.
export function decode(f, bytes) {
  if (bytes.length !== f.width * f.height) throw new Error(`field: ${bytes.length} bytes, want ${f.width * f.height}`);
  return { at: (a, b) => dequantize(bytes[b * f.width + a], f.range), solid: (a, b) => bytes[b * f.width + a] === SOLID };
}

// What is wrong with a manifest, given the case ids its stop expects (empty when it is fine).
export function problems(f, ids) {
  const bad = [];
  if (!PLANES.includes(f.plane)) bad.push(`plane ${f.plane}`);
  if (!QUANTITIES.includes(f.quantity)) bad.push(`quantity ${f.quantity}`);
  if (!(f.originMm?.length === 3 && f.originMm.every(Number.isFinite))) bad.push("originMm");
  if (!(f.cellMm > 0) || !Number.isInteger(f.width) || !Number.isInteger(f.height) || f.width < 1 || f.height < 1) bad.push("grid size");
  if (!(f.range?.length === 2 && f.range[0] < f.range[1])) bad.push("range");
  const got = Object.keys(f.cases ?? {});
  if (got.join() !== ids.join()) bad.push(`cases ${got.join()} ≠ ${ids.join()}`);
  const point = p => p?.length === 3 && p.every(Number.isFinite);
  for (const [id, c] of Object.entries(f.cases ?? {})) {
    if (!Array.isArray(c.lines) || !c.lines.every(l => Array.isArray(l) && l.every(point))) bad.push(`${id}: lines`);
    if (!Array.isArray(c.guides) || !c.guides.every(g => ["arrow", "line"].includes(g.kind) && g.points?.length >= 2 && g.points.every(point))) bad.push(`${id}: guides`);
    if (c.follow && !c.follow.every(i => Number.isInteger(i) && c.lines[i])) bad.push(`${id}: follow`);
  }
  return bad;
}

// Component airflow files (lib/model/part-field.js): the grid's orientation and byte format on a small asymmetric fixture,
// then every exported part a stop points at: manifest, bytes, and guides that agree with the air around them.
import { test } from "node:test";
import assert from "node:assert/strict";
import { readFileSync, existsSync } from "node:fs";
import { centre, corners, encode, decode, quantize, dequantize, problems, SOLID } from "../../lib/model/part-field.js";
import { loadCars } from "./helpers.mjs";

const root = new URL("../../", import.meta.url);
const fixture = plane => ({ plane, originMm: [100, 20, 30], cellMm: 10, width: 3, height: 2, quantity: "speed-over-inlet", range: [-1, 1], cases: { a: { lines: [], guides: [] } } });

test("part field: cell centres run against x along a row and up the plane down the rows, from the first cell's centre", () => {
  const xz = fixture("xz"), xy = fixture("xy");
  assert.deepEqual(centre(xz, 0, 0), [100, 20, 30]);
  assert.deepEqual(centre(xz, 2, 0), [80, 20, 30], "a column further is 10 mm further back");
  assert.deepEqual(centre(xz, 0, 1), [100, 20, 40], "a row further is 10 mm higher");
  assert.deepEqual(centre(xy, 0, 1), [100, 30, 30], "on a plan view a row further is 10 mm further left");
  assert.deepEqual(corners(xz), [[105, 20, 25], [75, 20, 25], [105, 20, 45], [75, 20, 45]], "outer edges half a cell beyond the centres");
  assert.deepEqual(corners(xy)[3], [75, 40, 30]);
});

test("part field: bytes are row-major from the bottom; the range's ends map to 0 and 254; 255 is solid, never a value", () => {
  const f = fixture("xz");
  // An asymmetric pattern: value = x/100 − (z − 30)/20 (front-low corner largest), solid at the rear top cell.
  const bytes = encode(f, (x, y, z) => (x === 80 && z === 40 ? null : x / 100 - (z - 30) / 20));
  assert.equal(bytes.length, 6);
  assert.deepEqual([...bytes], [quantize(1, f.range), quantize(0.9, f.range), quantize(0.8, f.range), quantize(0.5, f.range), quantize(0.4, f.range), SOLID]);
  assert.equal(quantize(-1, f.range), 0); assert.equal(quantize(1, f.range), 254); assert.equal(quantize(7, f.range), 254); assert.equal(quantize(-7, f.range), 0);
  assert.equal(dequantize(0, f.range), -1); assert.equal(dequantize(254, f.range), 1); assert.equal(dequantize(SOLID, f.range), null);
  const d = decode(f, bytes);
  assert.ok(Math.abs(d.at(0, 0) - 1) < 0.01 && Math.abs(d.at(2, 0) - 0.8) < 0.01 && Math.abs(d.at(0, 1) - 0.5) < 0.01);
  assert.equal(d.at(2, 1), null); assert.ok(d.solid(2, 1) && !d.solid(1, 1));
  assert.throws(() => decode(f, bytes.subarray(1)), /5 bytes, want 6/);
});

test("part field: a manifest's problems name what is wrong", () => {
  assert.deepEqual(problems(fixture("xz"), ["a"]), []);
  assert.deepEqual(problems(fixture("xz"), ["a", "b"]), ["cases a ≠ a,b"]);
  assert.deepEqual(problems({ ...fixture("yz"), range: [1, 0] }, ["a"]), ["plane yz", "range"]);
  const f = fixture("xy"); f.cases.a.guides = [{ kind: "arrow", points: [[0, 0, 0]] }];
  assert.deepEqual(problems(f, ["a"]), ["a: guides"]);
});

// Every exported part: the stop's case ids, the files and their sizes, and lessons the air itself carries.
const parts = (await loadCars()).flatMap(car => car.components.filter(c => c.subsystem === "race-aero").map(c => ({ car, c })));
test("every component tunnel a stop shows has its files", () => assert.ok(parts.length >= 4, `${parts.length} parts`));
for (const { car, c } of parts) {
  test(`${car.slug} ${c.id}: field, cases and guides agree with the air`, () => {
    const dir = new URL(c.params.data, root), ids = c.params.cases.map(k => k.id);
    assert.ok(ids.includes(c.params.start), "starts on one of its cases");
    const f = JSON.parse(readFileSync(new URL("field.json", dir)));
    assert.deepEqual(problems(f, ids), []);
    const cells = Object.fromEntries(ids.map(id => {
      assert.ok(existsSync(new URL(`${id}.bin`, dir)), `${id}.bin`);
      return [id, decode(f, new Uint8Array(readFileSync(new URL(`${id}.bin`, dir))))];
    }));
    const near = (id, p, r) => {   // fluid values within r cells of point p (on the plane)
      const out = [];
      for (let b = 0; b < f.height; b++) for (let a = 0; a < f.width; a++) {
        const q = centre(f, a, b), v = cells[id].at(a, b);
        if (v != null && Math.hypot(q[0] - p[0], q[1] - p[1], q[2] - p[2]) <= r * f.cellMm) out.push(v);
      }
      return out;
    };
    const mean = a => a.reduce((s, v) => s + v, 0) / a.length;
    for (const id of ids) {
      for (const g of f.cases[id].guides) {
        const [p0, p1] = g.points;
        if (g.kind === "arrow" && f.quantity === "vertical-speed-over-inlet") {
          const around = near(id, p0, 2.5); assert.ok(around.length >= 4, `${id}: air around the arrow`);
          assert.equal(Math.sign(p1[2] - p0[2]), Math.sign(mean(around)), `${id}: the arrow tips the way the air moves (mean ${mean(around).toFixed(3)})`);
        }
        if (g.below != null) {   // a line marking where the field is below a threshold: inside below, just beyond it above
          const v = near(id, p0.map((x, k) => (x + p1[k]) / 2), 0.75);
          assert.ok(v.length && mean(v) < g.below, `${id}: the marked band is slow (${mean(v)?.toFixed(2)})`);
        }
      }
    }
    if (ids.length > 1) {   // the air itself changes between the cases, not only the bodywork
      let changed = 0;
      for (let b = 0; b < f.height; b++) for (let a = 0; a < f.width; a++) {
        const u = cells[ids[0]].at(a, b), v = cells[ids[1]].at(a, b);
        if (u != null && v != null && Math.abs(u - v) > 0.1 * (f.range[1] - f.range[0])) changed++;
      }
      assert.ok(changed >= 4, `${changed} air cells change by a tenth of the scale`);
    }
  });
}

// Front-corner solids for the local 3-D tunnels (tools/cfd/part.mjs: w196-wheel, evo-arch), half car with the mirror at
// y = 0 as in the whole-car runs. Cells: x = x0 − (i + ½)h, y = (j + ½)h, z = (k + ½)h (mm, each stop's own frame: origin
// front axle centre on the ground); codes 0 air, 1 body, 2 tyre. Each domain ends behind the corner with the body running
// on through the outlet (only the corner is studied). Tyres stand still on the moving road, cut flat 48 mm above it (a whole
// number of cells on both grids, 24 and 16 mm), so the clearance is the same on each grid.
//
// W 196 R (assumed sizes, from its stop's ghost outline and photo fit): front tyre 340 mm radius, 150 mm wide, centred at
// y = 665. "enclosed": the 1955 streamliner's body, 820 mm half-width behind x = 500, a rounded nose to x = 1380, underside
// 150 mm up, top from the stop's centre-plane section with a fender bulge over the wheel, and a wheelhouse carved round the
// tyre (40 mm clear inside, 32 mm to the outer skin), open below the body. "exposed": the open-wheel car's body, a rounded
// nose to x = 950 widening to 330 mm half-width, 150–750 mm high: the tyre stands in free air. Suspension arms left out.
//
// Evo II: the game mesh's body (tools/cfd/geometry.mjs voxelize, column fill) clipped flat at 1000 mm, with a wheelhouse
// carved round its front tyre (333 mm radius, 135 mm half-width at y = 675): every body cell inside 378 mm of the hub and
// outboard of y = 495 is air. That opens the arch as on the car (the flare above the arch line stays) and keeps the inner
// wheelhouse wall.
import { voxelize } from "./geometry.mjs";

export const GAP = 48;
export const W196 = { tyre: { r: 340, half: 75, y: 665 }, hub: 340 };
export const EVO = { tyre: { r: 333, half: 135, y: 675 }, hub: 333 };

// Lattice for a part at cell size h: x from x0 back to x1, y from 0 to Y, z from 0 to Z (mm).
export const lattice = ({ x0, x1, Y, Z }, h) => ({ h, x0, nx: Math.round((x0 - x1) / h), ny: Math.round(Y / h), nz: Math.round(Z / h) });
export const DOMAIN = {
  "w196-wheel": { x0: 2400, x1: -2000, Y: 1800, Z: 1400 },
  "evo-arch": { x0: 1767, x1: -2000, Y: 1800, Z: 1600 },
};

const lerp = (pts, x) => {   // piecewise-linear z(x) through [[x, z], …] sorted by falling x
  if (x >= pts[0][0]) return pts[0][1];
  for (let n = 1; n < pts.length; n++) if (x >= pts[n][0]) { const [xa, za] = pts[n - 1], [xb, zb] = pts[n]; return zb + (za - zb) * (x - xb) / (xa - xb); }
  return pts.at(-1)[1];
};
const tyre = ({ r, half, y }, hub) => (x, yy, z) => z > GAP && Math.abs(yy - y) <= half && x * x + (z - hub) ** 2 < r * r;

// Streamliner: plan half-width, top and underside along x; rounded edges in cross-section.
const STREAM_TOP = [[1380, 420], [1300, 540], [1100, 640], [900, 700], [600, 740], [-300, 760], [-700, 770]];
function enclosed(x, y, z) {
  const t = Math.max(0, (x - 500) / 880); if (t >= 1) return false;
  const w = 820 * Math.sqrt(1 - t * t), bottom = x > 1250 ? 150 + 110 * (x - 1250) / 130 : 150;
  let top = lerp(STREAM_TOP, x);
  if (Math.abs(x) < 520 && y > 480) top = Math.max(top, 790 - 120 * (x / 520) ** 2);   // fender bulge over the wheel
  if (y > w || z < bottom || z > top) return false;
  const rt = 220, rb = 80;   // shoulder and lower edge radii
  if (y > w - rt && z > top - rt && (y - (w - rt)) ** 2 + (z - (top - rt)) ** 2 > rt * rt) return false;
  if (y > w - rb && z < bottom + rb && (y - (w - rb)) ** 2 + (z - (bottom + rb)) ** 2 > rb * rb) return false;
  // Wheelhouse round the front tyre, open below the body.
  if (x * x + (z - W196.hub) ** 2 < (W196.tyre.r + 40) ** 2 && y > W196.tyre.y - W196.tyre.half - 40 && y < W196.tyre.y + W196.tyre.half + 32) return false;
  return true;
}
// Open-wheel body: a rounded box section (exponent 2.5) centred 450 mm up, growing from the nose.
function exposed(x, y, z) {
  const t = Math.max(0, (x + 100) / 1050); if (t >= 1) return false;
  const s = Math.sqrt(1 - t * t), wy = 330 * s, hz = 300 * s;
  return (y / wy) ** 2.5 + (Math.abs(z - 450) / hz) ** 2.5 < 1;
}

function fill(L, f) {
  const { h, x0, nx, ny, nz } = L, solid = new Uint8Array(nx * ny * nz);
  for (let k = 0; k < nz; k++) for (let j = 0; j < ny; j++) for (let i = 0; i < nx; i++) {
    const v = f(x0 - (i + 0.5) * h, (j + 0.5) * h, (k + 0.5) * h);
    if (v) solid[(k * ny + j) * nx + i] = v;
  }
  return solid;
}

export function w196(mode, h) {
  const L = lattice(DOMAIN["w196-wheel"], h), wheel = tyre(W196.tyre, W196.hub), body = mode === "enclosed" ? enclosed : exposed;
  return { ...L, solid: fill(L, (x, y, z) => (wheel(x, y, z) ? 2 : body(x, y, z) ? 1 : 0)) };
}

export function evo(mesh, h) {
  const L = lattice(DOMAIN["evo-arch"], h), { solid } = voxelize(mesh, L, "base"), { nx, ny, nz, x0 } = L, wheel = tyre(EVO.tyre, EVO.hub);
  for (let k = 0; k < nz; k++) for (let j = 0; j < ny; j++) for (let i = 0; i < nx; i++) {
    const c = (k * ny + j) * nx + i, x = x0 - (i + 0.5) * h, y = (j + 0.5) * h, z = (k + 0.5) * h;
    if (solid[c] >= 2 || z > 1000) solid[c] = 0;   // the whole-car wheels go; the body is clipped flat
    if (solid[c] && y > EVO.tyre.y - EVO.tyre.half - 45 && x * x + (z - EVO.hub) ** 2 < (EVO.tyre.r + 45) ** 2) solid[c] = 0;
    if (wheel(x, y, z)) solid[c] = 2;
  }
  return { ...L, solid };
}

// A slice of a solid as text, for checking a mask before a long run: plane "z" (plan, rows = y from the top down), "y"
// (side, rows = z) or "x" (cross-section, rows = z, columns = y), through the cell nearest `at` mm; every `step`-th cell.
export function sketch({ solid, h, x0, nx, ny, nz }, plane, at, { step = 1, x = null } = {}) {
  const at3 = (i, j, k) => solid[(k * ny + j) * nx + i], ch = v => " #o"[v] ?? "?", rows = [];
  const i0 = x ? Math.max(0, Math.round((x0 - x[0]) / h)) : 0, i1 = x ? Math.min(nx, Math.round((x0 - x[1]) / h)) : nx;
  const n = Math.round(at / h - 0.5);
  if (plane === "z") for (let j = ny - 1; j >= 0; j -= step) { let s = ""; for (let i = i0; i < i1; i += step) s += ch(at3(i, j, n)); rows.push(s); }
  if (plane === "y") for (let k = nz - 1; k >= 0; k -= step) { let s = ""; for (let i = i0; i < i1; i += step) s += ch(at3(i, n, k)); rows.push(s); }
  if (plane === "x") { const i = Math.round((x0 - at) / h - 0.5); for (let k = nz - 1; k >= 0; k -= step) { let s = ""; for (let j = 0; j < ny; j += step) s += ch(at3(i, j, k)); rows.push(s); } }
  return rows.join("\n");
}

// Component airflow for the Evo II and W 196 R stops: node tools/cfd/part.mjs <part> <command> [case] [cell mm]
//   wing reference   the whole-car runs (tools/cfd/out/{base,flap}-{28,40}): probe above the wing's trailing edge on both
//                    grids, and the 28 mm side crop, into out/wing/ (needs run.mjs's raw volumes)
//   splitter solve   2-D section of the nose (lib/model/flow.js) with the lip in or forward, 5 and 2.5 mm, + a 5 mm run in
//                    a larger tunnel; one case and grid with [case] [cell mm] (case "in-big" for the larger tunnel)
//   w196-wheel solve 3-D front corner (tools/cfd/corner.mjs), enclosed and exposed, 24 and 16 mm
//   evo-arch solve   3-D front corner of the Evo with its flared arch, 24 and 16 mm
//   <part> export    checks the complete set of runs, then writes stops/<slug>/cfd/<part>/ (field.json, <case>.bin:
//                    lib/model/part-field.js) and the run record tools/cfd/results/<part>.json (checked in)
// Raw outputs stay in tools/cfd/out/<part>/ (git-ignored). Each solve settles for a few flow-throughs, then averages three
// successive windows; a result is published where its sign repeats on both grids and its size clears the windows' scatter.
import { mkdirSync, writeFileSync, readFileSync, existsSync } from "node:fs";
import { cpus } from "node:os";
import { load, volume, probe, trace, OUT } from "./volume.mjs";
import { encode, centre, problems } from "../../lib/model/part-field.js";
import { rasterize, createTunnel } from "../../lib/model/flow.js";

const [part, cmd, only, onlyH] = process.argv.slice(2);
const STOPS = new URL("../../stops/", import.meta.url), RESULTS = new URL("./results/", import.meta.url);
const dirOf = p => new URL(`./${p}/`, OUT);
const write = (url, data) => { mkdirSync(new URL("./", url), { recursive: true }); writeFileSync(url, data); };
const save = (p, name, meta, arrays, solid) => {
  write(new URL(`${name}.json`, dirOf(p)), JSON.stringify(meta, null, 1));
  write(new URL(`${name}.bin`, dirOf(p)), Buffer.concat(arrays.map(a => Buffer.from(a.buffer, a.byteOffset, a.byteLength))));
  write(new URL(`${name}.solid`, dirOf(p)), solid);
};
const mean = a => a.reduce((s, v) => s + v, 0) / a.length, sd = a => Math.sqrt(mean(a.map(v => (v - mean(a)) ** 2)));
const r1 = v => Math.round(v * 10) / 10, r3 = v => Math.round(v * 1000) / 1000;
// A change is shown when it has the same sign on both grids and clears two standard errors of the windows on each.
const settled = (a, b) => Math.sign(a.d) === Math.sign(b.d) && [a, b].every(g => Math.abs(g.d) > 2 * g.se);
const change = (wa, wb) => ({ d: mean(wb) - mean(wa), se: Math.hypot(sd(wa), sd(wb)) / Math.sqrt(Math.min(wa.length, wb.length)) });

// ---------------------------------------------------------------- wing (whole-car crop)
const WING = {
  box: { x: [-3920, -3750], y: [200, 300], z: [1230, 1290] },
  crop: { x: [-4300, -3150], z: [810, 1420], y: 238 },
  seeds: [960, 1040, 1100, 1160, 1200, 1250, 1300, 1360],   // z (mm) at x = −3100 on the crop's plane
};
function wingReference() {
  const res = {};
  for (const h of [28, 40]) for (const c of ["base", "flap"]) {
    const r = load(`${c}-${h}`), p = probe(r, WING.box);
    res[`${c}-${h}`] = { cells: p.n, angle: r1(p.angle), rearward: r3(p.rearward), up: r3(p.up) };
  }
  const diff = h => { const a = load(`base-${h}`).solid, b = load(`flap-${h}`).solid; let n = 0; for (let c = 0; c < a.length; c++) if (a[c] !== b[c]) n++; return n; };
  const rec = { source: "whole-car runs tools/cfd/run.mjs base|flap 28|40 9000 (uniform inflow, half car, still wheels)", box: WING.box, probe: res, changedCells: { 28: diff(28), 40: diff(40) } };
  write(new URL("reference.json", dirOf("wing")), JSON.stringify(rec, null, 1));
  console.log(JSON.stringify(rec, null, 1));
}
function wingExport() {
  const ref = JSON.parse(readFileSync(new URL("reference.json", dirOf("wing")))), h = 28;
  const runs = { base: load(`base-${h}`), flap: load(`flap-${h}`) };
  const r = runs.base, [i0, j, k0] = r.cell(WING.crop.x[1], WING.crop.y, WING.crop.z[0]), [i1, , k1] = r.cell(WING.crop.x[0], WING.crop.y, WING.crop.z[1]);
  const origin = r.centre(i0, j, k0);
  const f = { plane: "xz", originMm: origin, cellMm: h, width: i1 - i0 + 1, height: k1 - k0 + 1, quantity: "vertical-speed-over-inlet", range: [-0.25, 0.25], cases: {} };
  const bins = {};
  // Where the raised flap stands, from the flap run's own extra cells on this plane: the line through them.
  const extra = []; for (let k = k0; k <= k1; k++) for (let i = i0; i <= i1; i++) { const c = r.at(i, j, k); if (runs.flap.solid[c] && !runs.base.solid[c]) extra.push(r.centre(i, j, k)); }
  extra.sort((a, b) => b[0] - a[0]);
  const flapLine = [extra[0], extra.at(-1)].map(p => p.map(Math.round));
  const [bx, , bz] = [mean(WING.box.x), 0, mean(WING.box.z)];
