    out[1] = w00 * uz[c] + w10 * uz[c + 1] + w01 * uz[c + nx] + w11 * uz[c + nx + 1];
    return out;
  }
  return { nx, nz, U, solid, ux, uz, rho, drag, step, cp, sample };
